import fs from "node:fs";
import { wordFrequencies, formatTop } from "./core.mjs";

/**
 * @param {{argv?: string[], env?: Record<string, string|undefined>, out?: NodeJS.WriteStream}} [deps]
 */
export function main({ argv = process.argv, env = process.env, out = process.stdout } = {}) {
  const file = argv[2];
  const topN = parseInt(env.TOP_N || "10", 10);
  const text = fs.readFileSync(file, "utf8");
  out.write(formatTop(wordFrequencies(text), topN));
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  main();
}
