// Everything testable lives here.

/**
 * Count word occurrences in text. Case-insensitive; words are runs of
 * [a-z'] after lowercasing (apostrophes inside words are kept).
 * @param {string} text
 * @returns {Map<string, number>} word -> count
 */
export function wordFrequencies(text) {
  const counts = new Map();
  for (const w of text.toLowerCase().split(/[^a-z']+/)) {
    if (!w) continue;
    counts.set(w, (counts.get(w) || 0) + 1);
  }
  return counts;
}

/**
 * Format the top N entries as "count\tword" lines.
 * Ordering: count descending, ties broken alphabetically ascending.
 * @param {Map<string, number>} counts
 * @param {number} topN
 * @returns {string} lines joined with "\n", trailing newline included if non-empty
 */
export function formatTop(counts, topN) {
  const top = Array.from(counts.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, Math.max(0, topN));
  return top.map(([w, c]) => `${c}\t${w}`).join("\n") + (top.length ? "\n" : "");
}
"})
print(result)

