result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wordfreq.test.mjs", "content": "import { test, describe } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { wordFrequencies, formatTop } from "./core.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));

describe("wordFrequencies", () => {
  test("counts words case-insensitively (case folding)", () => {
    const counts = wordFrequencies("The the THE");
    assert.deepEqual(Object.fromEntries(counts), { the: 3 });
  });

  test("keeps apostrophes inside words (don't)", () => {
    const counts = wordFrequencies("Don't stop, don't ever stop");
    assert.equal(counts.get("don't"), 2);
    assert.equal(counts.get("stop"), 2);
    assert.equal(counts.get("ever"), 1);
    assert.equal(counts.size, 3);
  });

  test("empty text yields an empty map", () => {
    assert.deepEqual(wordFrequencies(""), new Map());
    assert.deepEqual(wordFrequencies("   \n\t... 12 34 !! "), new Map());
  });
});

describe("formatTop", () => {
  test("orders by count desc, ties broken alphabetically asc", () => {
    // b/a tie at 3; z/c/x tie at 1 -> a before b, c before x before z
    const counts = wordFrequencies("z a c x b a B A");
    assert.equal(
      formatTop(counts, 10),
      "3\ta\n2\tb\n1\tc\n1\tx\n1\tz\n"
    );
  });

  test("topN larger than vocabulary returns everything", () => {
    const counts = wordFrequencies("one two two three three three");
    assert.equal(formatTop(counts, 100), "3\tthree\n2\ttwo\n1\tone\n");
  });

  test("topN truncates output", () => {
    const counts = wordFrequencies("a b c d e");
    assert.equal(formatTop(counts, 2), "1\ta\n1\tb\n");
  });

  test("empty counts produce empty string", () => {
    assert.equal(formatTop(new Map(), 5), "");
  });

  test("round trip: format of frequencies for sample text", () => {
    const out = formatTop(wordFrequencies("Hello world. Hello!"), 10);
    assert.equal(out, "2\thello\n1\tworld\n");
  });
});

describe("cli integration", () => {
  test("spawns node cli.mjs sample.txt with TOP_N=3 and asserts exact stdout", () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "wordfreq-"));
    try {
      const fixture = path.join(tmp, "sample.txt");
      fs.writeFileSync(
        fixture,
        "Don't worry. Don't stop.\nWorry is the mind killer; stop the worry!\n"
      );

      const stdout = execFileSync(
        process.execPath,
        ["cli.mjs", fixture],
        {
          cwd: here,
          env: { ...process.env, TOP_N: "3" },
          encoding: "utf8",
        }
      );

      assert.equal(stdout, "4\tworry\n2\tdon't\n2\tstop\n");
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });
});
"})
print(result)

